tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import { copyFileSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const disposable = mkdtempSync(resolve('.catalog-review-'));
try {
  for (const side of ['base', 'head']) {
    const source = resolve('review', side);
    const { loadCatalog, setPinned, saveCatalog, pinnedTitles } =
      await import(pathToFileURL(resolve(source, 'src/catalog.mjs')));
    for (const [id, pinned] of [['a', true], ['b', false]]) {
      const path = resolve(disposable, side + '-' + id + '.json');
      copyFileSync(resolve(source, 'fixture/catalog.json'), path);
      const updated = setPinned(loadCatalog(path), id, pinned);
      saveCatalog(path, updated);
      const reloaded = loadCatalog(path);
      console.log(JSON.stringify({
        side, id, pinned,
        expected: pinnedTitles(updated),
        actual: pinnedTitles(reloaded),
        written: JSON.parse(readFileSync(path, 'utf8')),
      }));
    }
  }
} finally {
  rmSync(disposable, { recursive: true });
}
NODE"
